schema_ddl:
CREATE TABLE dipendenti (
    matricola INT PRIMARY KEY,
    nome TEXT NOT NULL,
    id_reparto INT,
    responsabile_reparto INT REFERENCES dipendenti(matricola)
);

CREATE TABLE reparti (
    id_reparto INT PRIMARY KEY,
    nome_reparto TEXT NOT NULL,
    sede TEXT
);

CREATE TABLE progetti (
    id_progetto INT PRIMARY KEY,
    nome_progetto TEXT NOT NULL,
    matricola INT REFERENCES dipendenti(matricola)
);
